import{_ as o,C as e,o as c,c as d,E as a,a2 as l}from"./chunks/framework.Cc8dJFaW.js";const f=JSON.parse('{"title":"能访问服务，不等于这次动作已经获批","description":"","frontmatter":{"title":"能访问服务，不等于这次动作已经获批","article_type":"comparative-study","edition":"research-center","research_question":"资源令牌、动作批准与事件规则分别绑定什么，批准查询是否区分同一主体的不同请求？","summary":"资源目标、批准查询与事件条件分别绑定不同对象。逐层审查能保留各自责任，也能避免把局部查询结果写成整体安全结论。","sources":["https://modelcontextprotocol.io/specification/latest/basic/authorization","https://raw.githubusercontent.com/GoetzKohlberg/sidjua/747b5bb125c8cc94e7cb99a581dc63bedb2c9bb2/src/pipeline/index.ts","https://raw.githubusercontent.com/GoetzKohlberg/sidjua/747b5bb125c8cc94e7cb99a581dc63bedb2c9bb2/src/pipeline/approval.ts","https://arxiv.org/html/2503.18666v3"],"date":"2026-11-26","column":"industry-architecture","category":"daily","pageClass":"runtime-v6-article","item_id":"SIG-20261126-001","lifecycle":"Published","cover":"/assets/covers/daily-2026-11-26-sig-20261126-001-final-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/industry/2026-11-26-sig-20261126-001.md","filePath":"zh/industry/2026-11-26-sig-20261126-001.md","lastUpdated":null}'),n={name:"zh/industry/2026-11-26-sig-20261126-001.md"};function s(b,t,h,p,u,g){const r=e("ArticleCover"),i=e("ArticleTableScroll");return c(),d("div",null,[a(r,{image:"/assets/covers/daily-2026-11-26-sig-20261126-001-final-cover.png",kicker:"研究成果",title:"能访问服务，不等于这次动作已经获批",summary:"资源目标、批准查询与事件条件分别绑定不同对象。逐层审查能保留各自责任，也能避免把局部查询结果写成整体安全结论。",version:"2026-11-26",languageHref:"/en/industry/2026-11-26-sig-20261126-001",languageLabel:"English"}),a(i,{language:"zh"}),t[0]||(t[0]=l('<h1 id="能访问服务-不等于这次动作已经获批" tabindex="-1">能访问服务，不等于这次动作已经获批 <a class="header-anchor" href="#能访问服务-不等于这次动作已经获批" aria-label="Permalink to &quot;能访问服务，不等于这次动作已经获批&quot;">​</a></h1><p>设想一个智能体已能访问受限服务，也找到了同一主体的批准记录，动作前还会检查规则。平台工程师仍要追问：批准针对的是这次请求，还是这一类工作？本文比较三种机制的绑定对象，给出一张逐层核对表。核心判断是：资源访问、动作批准与事件谓词分别回答不同问题，任一层的证据都不能补出另一层缺失的决定。</p><h2 id="三种机制-各自认的是谁" tabindex="-1">三种机制，各自认的是谁 <a class="header-anchor" href="#三种机制-各自认的是谁" aria-label="Permalink to &quot;三种机制，各自认的是谁&quot;">​</a></h2><p>MCP（模型上下文协议）的授权规范在本轮保存的页面中，要求客户端在授权和令牌请求中标明目标资源，并要求服务端检查令牌受众。它约束的是“令牌是否用于预期资源”，不是替每笔业务操作定义完整批准生命周期。这些是规范要求，不能写成某个部署已符合要求。<a href="https://modelcontextprotocol.io/specification/latest/basic/authorization" target="_blank" rel="noreferrer">授权规范</a></p><p>SIDJUA（智能体治理软件）提供另一类材料：动作前的批准查询。被检查管线按禁止项、批准、预算、分类和策略顺序处理；阻断或暂停会短路后续处理。批准层过关也仍可能被后续层挡下。这是固定源码路径的观察，不代表已完成入口清单或旁路测试。<a href="https://raw.githubusercontent.com/GoetzKohlberg/sidjua/747b5bb125c8cc94e7cb99a581dc63bedb2c9bb2/src/pipeline/index.ts" target="_blank" rel="noreferrer">管线源码</a></p><p>AgentSpec（智能体运行约束语言）则把规则放在事件检查点：事件触发谓词检查，再选择停止、人工检查、预定义动作或自我检查。它的关键对象是“此处能观察到的条件”，而不是令牌受众，也不是自动取得某笔操作的人类同意。<a href="https://arxiv.org/html/2503.18666v3" target="_blank" rel="noreferrer">论文第 3.2—4 节</a></p><table tabindex="0"><thead><tr><th>层次</th><th>直接检查的对象</th><th>单凭它还不能知道什么</th></tr></thead><tbody><tr><td>资源授权</td><td>令牌目标资源与受众</td><td>这次动作参数是否获批</td></tr><tr><td>批准查询</td><td>实际查询谓词选中的批准行</td><td>所选记录是否对应当前动作，及最终副作用是否允许</td></tr><tr><td>事件规则</td><td>指定检查点上的条件</td><td>未布置检查点的路径、未表达的条件及完整长期轨迹</td></tr></tbody></table><p>这是一张证据责任表，不是三款系统的安全排名。规范、实现与论文机制处在不同层面，不能把“都与治理有关”当成可互换的保证。</p><h2 id="保存了请求编号-查询未必使用它" tabindex="-1">保存了请求编号，查询未必使用它 <a class="header-anchor" href="#保存了请求编号-查询未必使用它" aria-label="Permalink to &quot;保存了请求编号，查询未必使用它&quot;">​</a></h2><p>一个明确标注的示意：主体先为目标甲、数量一获得批准，后来提交目标乙、数量一千。如果合同是单次具体动作批准，审核需要看哪些字段仍相同；若合同本就允许一段时间内的整类工作，则应检查该范围是否被明确告知和记录。广泛复用本身不等于漏洞。</p><p>固定提交中的批准查找函数按主体、规则、记录状态和创建时间选择最近一行。请求编号、序列化动作与部门虽可保存在记录中，却没有进入该查询的比较条件。注释提到请求编号匹配，不能代替实际谓词。这个行为已经是本地近期研究关注的对象；这里用它定位层次，不把它包装成新发现。<a href="https://raw.githubusercontent.com/GoetzKohlberg/sidjua/747b5bb125c8cc94e7cb99a581dc63bedb2c9bb2/src/pipeline/approval.ts" target="_blank" rel="noreferrer">批准源码</a></p><p>同次 Analysis（研究分析阶段）已执行九个内部隔离探针：原函数通过类型擦除运行于真实内存数据库，配合合成请求和记录。请求编号、动作及部门不同的记录仍被选中；不同主体、不同规则、过期记录和排除状态的对照未被选中。待决与拒绝行也可在不同请求间被选中；元数据格式错误时，行仍被选中而元数据变为空。结果支持查询层的匹配范围，不等于动作已放行。完整应用、恢复入口、调用方不变量与真实副作用均未运行。</p><p><a href="/joinwell52/assets/evidence/2026-11-26-sig-20261126-001/experiment-evidence.json">内部探针的完整用例与结果</a></p><p>这组证据的工程用途是检查“保存字段”与“判定字段”的差集。它没有测量生产可达的授权绕过，也没有证明任何受害事件发生。资源令牌即使正确，也不能修补这一查询中缺少的比较；反过来，查询更严格也不能替代令牌受众检查。</p><h2 id="加上规则语言-也要问规则看到了什么" tabindex="-1">加上规则语言，也要问规则看到了什么 <a class="header-anchor" href="#加上规则语言-也要问规则看到了什么" aria-label="Permalink to &quot;加上规则语言，也要问规则看到了什么&quot;">​</a></h2><p>规则可以补充动作约束，但前提是触发位置和谓词表达确实覆盖目标风险。论文作者报告，自动生成规则在代码风险任务中的执行率为 87.26%，并讨论了枚举敏感文件导致的过拟合；自动生成规则的结果弱于手写规则。这是作者报告，未在本轮复现，也不是对上述批准实现的独立安全验证。<a href="https://arxiv.org/html/2503.18666v3" target="_blank" rel="noreferrer">论文第 5.3 节</a></p><p>论文还明确保留离散检查点的边界：它没有完成基于整条轨迹的安全分析。一个检查点可以正确判断眼前条件，却不能因此宣称任意长期行为安全。我们的解释是：若操作身份没有进入该点可见的数据，规则语言的存在不会凭空增加身份信息。是否能补足，取决于实际传入字段、规则和执行路径，而不是语言名称。<a href="https://arxiv.org/html/2503.18666v3" target="_blank" rel="noreferrer">论文第 6.3 节</a></p><p>三方作者独立，分别对各自规范、实现和方法负责；没有一方在这些材料中复现另两方系统。源码可公开检查、论文被发表或被引用，都不增加未做过的实验强度。</p><h2 id="把一次批准沿责任链查到底" tabindex="-1">把一次批准沿责任链查到底 <a class="header-anchor" href="#把一次批准沿责任链查到底" aria-label="Permalink to &quot;把一次批准沿责任链查到底&quot;">​</a></h2><p>对需要具体人类同意的高风险写操作，可以采用下面的建议检查法。它是审查目标，不是三种材料已经共同实现的流程。</p><table tabindex="0"><thead><tr><th>阶段与责任主体</th><th>输入与应保留的输出</th><th>何时停止或重新询问</th></tr></thead><tbody><tr><td>客户端与资源服务</td><td>目标资源、令牌及受众检查结果</td><td>目标或受众不符</td></tr><tr><td>可信请求构造方</td><td>主体、目标、规范化参数及前置状态</td><td>身份或参数来源不清</td></tr><tr><td>批准方与批准存储</td><td>明确批准范围、期限与适用条件</td><td>超出范围、过期或前置状态变化</td></tr><tr><td>执行入口</td><td>当前请求与有效批准的对应关系</td><td>无法建立对应关系</td></tr><tr><td>执行与恢复层</td><td>消费记录、结果与重试身份</td><td>无法区分网络重试、重复消费和重新批准</td></tr></tbody></table><p>先写下批准究竟是单次还是范围授权，再逐项改变请求编号、目标、参数、状态和时间，观察真实入口的结果。还要单独核对单次消费、防重放、撤销与执行之间的竞争，以及进程、容器或操作系统兜底。应用层规则存在，并不说明这些机制都已实现。</p><h2 id="哪些问题仍不能由这些材料裁定" tabindex="-1">哪些问题仍不能由这些材料裁定 <a class="header-anchor" href="#哪些问题仍不能由这些材料裁定" aria-label="Permalink to &quot;哪些问题仍不能由这些材料裁定&quot;">​</a></h2><p>低风险只读服务可能只需要资源范围令牌，并不普遍需要逐次人工批准。这是本方法不应机械套用的场景。另一个替代解释是：批准查询有意采用工作范围授权，或者调用方已限制请求复用；隔离函数探针无法排除这两种情况。</p><p>本轮依据同日保存的规范页面、论文版本与固定提交。规范的“最新”地址会变化，观察范围由本轮提取文件的哈希限定；批准源码固定在提交 747b5bb125c8cc94e7cb99a581dc63bedb2c9bb2。未执行部署令牌审计、并发撤销、全入口拒绝、宿主隔离或完整生命周期测试。</p><p>下一步应先确认维护者承诺的授权范围，再在真实请求与恢复入口检查“旧批准遇到新参数”以及“撤销与执行竞争”。只有补上这些证据，才能从查询层判断走向操作层判断；目前可交付给读者的是分层审查方法，而非整体安全认证。</p><h3 id="证据与引用" tabindex="-1">证据与引用 <a class="header-anchor" href="#证据与引用" aria-label="Permalink to &quot;证据与引用&quot;">​</a></h3><ul><li>MCP 规范维护者：《授权》，规范页面，本轮保存于 2026-11-26。<a href="https://modelcontextprotocol.io/specification/latest/basic/authorization" target="_blank" rel="noreferrer">目标资源、令牌使用与受众检查</a>。</li><li>SIDJUA 项目维护者：管线与批准查询源码，提交 747b5bb125c8cc94e7cb99a581dc63bedb2c9bb2，本轮检查于 2026-11-26。<a href="https://raw.githubusercontent.com/GoetzKohlberg/sidjua/747b5bb125c8cc94e7cb99a581dc63bedb2c9bb2/src/pipeline/index.ts" target="_blank" rel="noreferrer">管线</a>、<a href="https://raw.githubusercontent.com/GoetzKohlberg/sidjua/747b5bb125c8cc94e7cb99a581dc63bedb2c9bb2/src/pipeline/approval.ts" target="_blank" rel="noreferrer">批准查询</a>。</li><li>新加坡管理大学作者团队：《AgentSpec：面向安全可靠大语言模型智能体的可定制运行约束》，论文第三版，2025-07-31。<a href="https://arxiv.org/html/2503.18666v3" target="_blank" rel="noreferrer">机制、评估与局限</a>。</li><li>本研究中心：2026-11-26 内部隔离查询实验；仅支持所述函数边界，不是独立复现。<a href="/joinwell52/assets/evidence/2026-11-26-sig-20261126-001/experiment-evidence.json">逐例输入与结果</a>。</li></ul>',28))])}const _=o(n,[["render",s]]);export{f as __pageData,_ as default};
